-- Discord IDs remain text so they round-trip without numeric coercion.
-- UUIDv7 values are generated by the application, not by a database default.
-- pg_trgm remains deferred until a measured search index requires it.
-- No trigger, RLS policy, partition, or materialized view is installed here.

CREATE FUNCTION public.is_discord_snowflake(value text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
PARALLEL SAFE
AS $$
    SELECT CASE
        WHEN value ~ '^[1-9][0-9]{0,19}$'
            THEN value::numeric <= 18446744073709551615::numeric
        ELSE false
    END
$$;
